const input = $('When Executed by Another Workflow').item.json;
const consultaRaw = input.consulta || '';
const precoMax = input.precoMax ? Number(String(input.precoMax).replace(/[^0-9]/g,'')) : null;
const precoMin = input.precoMin ? Number(String(input.precoMin).replace(/[^0-9]/g,'')) : null;

const dados = $input.item.json;
// API retorna { data: { totalItens, itens: [...] } }
const itens = dados.data?.itens || dados.itens || [];

if (!itens.length) {
  return [{ json: { resultado: 'Estoque indisponível no momento.' } }];
}

function norm(s) {
  return (s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Tipos PERMITIDOS (whitelist)
const tiposPermitidos = ['celular','notebook','tablet','perfume'];

// Filtra apenas disponíveis e tipos permitidos
let filtrados = itens.filter(p => {
  const disp = (p.disponibilidade || '').toLowerCase();
  if (!disp.includes('dispon')) return false;
  const tipo = norm(p.tipoProdutoDescricao || '');
  return tiposPermitidos.some(t => tipo.includes(t));
});

// Filtro por preço
if (precoMax) filtrados = filtrados.filter(p => Number(p.valorVenda || 0) <= precoMax);
if (precoMin) filtrados = filtrados.filter(p => Number(p.valorVenda || 0) >= precoMin);

// Filtro por consulta — busca em aparelhoDescricao e descricao
if (consultaRaw.trim()) {
  const consultaNorm = norm(consultaRaw);
  // Remove stopwords curtas
  const stopwords = ['tem','vc','voce','um','uma','de','do','da','que','pra','pro','me','com'];
  const termos = consultaNorm.split(' ').filter(t => t.length > 2 && !stopwords.includes(t));

  if (termos.length > 0) {
    const porTermos = filtrados.filter(p => {
      const aparelho = norm(p.aparelhoDescricao || '');
      const desc = norm(p.descricao || '');
      // Todos os termos devem bater (every) — mais preciso
      return termos.every(t => aparelho.includes(t) || desc.includes(t));
    });
    // Se não achou com every, tenta com some (pelo menos 1 termo)
    if (porTermos.length > 0) {
      filtrados = porTermos;
    } else {
      const porAlgum = filtrados.filter(p => {
        const aparelho = norm(p.aparelhoDescricao || '');
        const desc = norm(p.descricao || '');
        return termos.some(t => aparelho.includes(t) || desc.includes(t));
      });
      if (porAlgum.length > 0) filtrados = porAlgum;
    }
  }
}

if (!filtrados.length) {
  return [{ json: { resultado: `Não encontrei esse produto no estoque no momento.` } }];
}

// Ordena por preço crescente
filtrados.sort((a, b) => Number(a.valorVenda || 0) - Number(b.valorVenda || 0));

// Deduplica por aparelhoId + cor + GB + estado
const vistos = new Map();
filtrados = filtrados.filter(p => {
  const chave = `${p.aparelhoId}-${p.corId}-${p.gbId}-${p.estadoProdutoId}`;
  if (vistos.has(chave)) return false;
  vistos.set(chave, true);
  return true;
});

// Formata resultado (máx 10)
const lista = filtrados.slice(0, 10).map(p => {
  let desc = (p.descricao || p.nome || 'Aparelho');
  desc = desc.replace(/^\d+\s*-\s*/, '').trim();
  desc = desc.replace(/\s*-\s*(IMEI\s*2?|SN|SKU)[\s:][^\n-]*/gi, '').trim();
  desc = desc.replace(/\s*-\s*Estado:\s*(NOVO|SEMINOVO)/gi, '').trim();
  desc = desc.replace(/(\s*-\s*\d+GB)+\s*$/i, '').trim();
  desc = desc.replace(/-\s*$/, '').trim();
  const estado = (p.estadoProdutoDescricao || '').toLowerCase();
  const estadoLabel = estado === 'seminovo' ? ' (seminovo)' : estado === 'novo' ? ' (novo)' : '';
  const preco = p.valorVenda
    ? `R$ ${Number(p.valorVenda).toLocaleString('pt-BR', {minimumFractionDigits: 2})}`
    : 'consultar preço';
  return `• ${desc}${estadoLabel} — ${preco}`;
}).join('\n');

const total = filtrados.length;
const rodape = total > 10
  ? `\n(${total} unidades disponíveis — mostrando as 10 mais baratas)`
  : `(${total} unidade${total > 1 ? 's' : ''} disponível)`;

return [{ json: { resultado: `${lista}\n${rodape}` } }];
